window.__votdWeek && window.__votdWeek({"week":"2028-12-11","reading":"Moroni 10","days":[{"d":"2028-12-11","ref":"Moroni 10:2","b":"Moroni","c":10,"v":2,"he":"וְאֶחְתֹּם אֶת־הַסְּפָרִים הָאֵלֶּה אַחֲרֵי דַבְּרִי דְבָרִים מְעַטִּים לְהַזְהִירְכֶם׃","en":"And I seal up these records, after I have spoken a few words by way of exhortation unto you."},{"d":"2028-12-12","ref":"Moroni 10:4","b":"Moroni","c":10,"v":4,"he":"וּבְקַבֶּלְכֶם אֶת־הַדְּבָרִים הָאֵלֶּה אַזְהִיר אֶתְכֶם כִּי תִשְׁאֲלוּ מֵאֱלֹהִים הָאָב אֲשֶׁר־לְעוֹלָם בְּשֵׁם הַמָּשִׁיחַ אִם־לֹא אֱמֶת הַדְּבָרִים הָאֵלֶּה וְאִם־שָׁאֹל תִּשְׁאֲלוּ בְּלֵב תָּמִים וֶאֱמוּנָה בַּמָּשִׁיחַ יַגְלֶה לָכֶם אֲמִתָּתָם בְּכֹחַ רוּחַ־הַקֹּדֶשׁ׃","en":"And when ye shall receive these things, I would exhort you that ye would ask God, the Eternal Father, in the name of Christ, if these things are not true; and if ye shall ask with a sincere heart, with real intent, having faith in Christ, he will manifest the truth of it unto you, by the power of the Holy Ghost."},{"d":"2028-12-13","ref":"Moroni 10:5","b":"Moroni","c":10,"v":5,"he":"וּבְכֹחַ רוּחַ־הַקֹּדֶשׁ תּוּכְלוּ לָדַעַת אֲמִתַּת כׇּל־דָּבָר׃","en":"And by the power of the Holy Ghost ye may know the truth of all things."},{"d":"2028-12-14","ref":"Moroni 10:9","b":"Moroni","c":10,"v":9,"he":"כִּי הִנֵּה לָאֶחָד נִתָּן בְּרוּחַ אֱלֹהִים לְלַמֵּד דְּבַר חׇכְמָה׃","en":"For behold, to one is given by the Spirit of God, that he may teach the word of wisdom;"},{"d":"2028-12-15","ref":"Moroni 10:20","b":"Moroni","c":10,"v":20,"he":"לָכֵן תִּהְיֶה אֱמוּנָה וְאִם־תִּהְיֶה אֱמוּנָה תִּהְיֶה גַּם־תִּקְוָה וְאִם־תִּהְיֶה תִּקְוָה יִהְיֶה גַּם חֶסֶד׃","en":"Wherefore, there must be faith; and if there must be faith there must also be hope; and if there must be hope there must also be charity."},{"d":"2028-12-16","ref":"Moroni 10:26","b":"Moroni","c":10,"v":26,"he":"וְאוֹי לָהֶם אֲשֶׁר יָסִירוּ אֶת־הַדְּבָרִים הָאֵלֶּה וְיָמוּתוּ כִּי יָמוּתוּ בְּחַטֹּאתָם וְלֹא יוּכְלוּ לְהִוָּשַׁע בְּמַלְכוּתוֹ וַאֲנִי מְדַבֵּר כְּפִי דִבְרֵי הַמָּשִׁיחַ וְלֹא אֲכַזֵּב׃","en":"And wo unto them who shall do these things away and die, for they die in their sins, and they cannot be saved in the kingdom of God; and I speak it according to the words of Christ; and I lie not."},{"d":"2028-12-17","ref":"Moroni 10:30","b":"Moroni","c":10,"v":30,"he":"וְעוֹד אַזְהִיר אֶתְכֶם כִּי תָבֹאוּ אֶל־הַמָּשִׁיחַ וְהַחֲזִיקוּ בְּכׇל־מַתָּנָה טוֹבָה וְאַל־תִּגְּעוּ בַּמַּתָּנָה הָרָעָה וְלֹא בַדָּבָר הַטָּמֵא׃","en":"And again I would exhort you that ye would come unto Christ, and lay hold upon every good gift, and touch not the evil gift, nor the unclean thing."}]});
